'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { FileIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import {
  countOfKind,
  fileLinesOf,
  GUARD_KEYS,
  numbered,
  PULL_REQUEST,
  type LineKind,
  type NumberedLine,
} from './data';
import {
  APPLY_MS,
  hasGuardOf,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  REPLY_MS,
  RESTING,
  SCRIPT,
  type ReviewState,
} from './session';
import { ReviewThread } from './thread';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const SIGN: Record<LineKind, string> = { same: ' ', added: '+', removed: '-' };

const LINE_TINT: Record<LineKind, string> = {
  same: '',
  added: 'bg-success/10',
  removed: 'bg-destructive/10',
};

const LINE_WORD: Record<LineKind, string> = {
  same: '',
  added: 'Added: ',
  removed: 'Removed: ',
};

function openCountOf(state: ReviewState) {
  const open = state.threads.filter((thread) => !thread.isResolved);
  return open.length;
}

function conversationsOf(count: number) {
  if (count === 0) {
    return 'Every conversation is resolved';
  }
  if (count === 1) {
    return '1 open conversation';
  }
  return `${count} open conversations`;
}

function spokenUnless(isDemonstrating: boolean, message: string) {
  if (isDemonstrating) {
    return '';
  }
  return message;
}

function pressedSolidOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-primary/85';
  }
  return undefined;
}

function plusClassOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-90 opacity-100';
  }
  return 'opacity-0';
}

/** The lines a suggestion just added light for a moment, then keep the tint of an added line. */
function freshClassOf(isFresh: boolean) {
  if (isFresh) {
    return 'transition-colors duration-1000 ease-out starting:bg-primary/30';
  }
  return undefined;
}

function lineNumberOf(line: NumberedLine) {
  return line.newNumber ?? line.oldNumber;
}

type DiffRowProps = {
  line: NumberedLine;
  canComment: boolean;
  isPlusPressed: boolean;
  onOpen: (lineKey: string) => void;
};

function DiffRow({ line, canComment, isPlusPressed, onOpen }: DiffRowProps) {
  const isFresh = GUARD_KEYS.has(line.key);
  const number = lineNumberOf(line);

  return (
    <div
      className={cn(
        'group/row flex items-start font-mono text-xs leading-6',
        LINE_TINT[line.kind],
        freshClassOf(isFresh)
      )}
    >
      <span className='flex h-6 w-7 shrink-0 items-center justify-center'>
        {canComment && (
          <button
            type='button'
            aria-label={`Comment on line ${number}`}
            onClick={() => onOpen(line.key)}
            className={cn(
              'bg-primary text-primary-foreground flex size-5 cursor-pointer items-center justify-center rounded-md transition-[opacity,scale] duration-150 outline-none group-hover/row:opacity-100 focus-visible:opacity-100 active:scale-[0.97] [@media(hover:none)]:opacity-60',
              plusClassOf(isPlusPressed)
            )}
          >
            <PlusIcon className='size-3.5' />
          </button>
        )}
      </span>
      <span className='text-muted-foreground/70 hidden w-8 shrink-0 text-end tabular-nums select-none @md:block'>
        {line.oldNumber}
      </span>
      <span className='text-muted-foreground/70 w-8 shrink-0 text-end tabular-nums select-none'>
        {line.newNumber}
      </span>
      <span
        aria-hidden='true'
        className='text-muted-foreground w-6 shrink-0 text-center select-none'
      >
        {SIGN[line.kind]}
      </span>
      <span className='sr-only'>{LINE_WORD[line.kind]}</span>
      <code className='min-w-0 flex-1 pe-3 break-all whitespace-pre-wrap'>
        {line.text}
      </code>
    </div>
  );
}

type CommentFieldProps = {
  draft: string;
  shouldFocus: boolean;
  isPostPressed: boolean;
  onChange: (text: string) => void;
  onPost: () => void;
  onCancel: () => void;
};

function CommentField({
  draft,
  shouldFocus,
  isPostPressed,
  onChange,
  onPost,
  onCancel,
}: CommentFieldProps) {
  const canPost = draft.trim() !== '';

  function handleKeys(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === 'Escape') {
      onCancel();
      return;
    }
    const hasModifier = event.metaKey || event.ctrlKey;
    const isPostKey = event.key === 'Enter' && hasModifier;
    if (isPostKey && canPost) {
      onPost();
    }
  }

  return (
    <div className='bg-card hairline-ring ring-foreground/12 has-[textarea:focus-visible]:ring-ring/25 dark:bg-foreground/[0.04] flex flex-col gap-2 rounded-lg p-2 font-sans shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-[box-shadow] duration-150 has-[textarea:focus-visible]:ring-[3px]'>
      <textarea
        value={draft}
        rows={2}
        autoFocus={shouldFocus}
        aria-label='Comment on this line'
        placeholder='Leave a comment for Coder'
        onChange={(event) => onChange(event.target.value)}
        onKeyDown={handleKeys}
        className='placeholder:text-muted-foreground/75 resize-none bg-transparent px-1.5 py-1 text-base leading-normal outline-none md:text-[13px]'
      />
      <div className='flex items-center justify-end gap-2'>
        <Button type='button' variant='ghost' size='sm' onClick={onCancel}>
          Cancel
        </Button>
        <Button
          type='button'
          size='sm'
          disabled={!canPost}
          onClick={onPost}
          className={pressedSolidOf(isPostPressed)}
        >
          Post comment
        </Button>
      </div>
    </div>
  );
}

export default function AgentReview02() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const shouldReduceMotion = useReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const hasGuard = hasGuardOf(state);
  const fileLines = fileLinesOf(hasGuard);
  const lines = numbered(fileLines);
  const additions = countOfKind(fileLines, 'added');
  const deletions = countOfKind(fileLines, 'removed');
  const openCount = openCountOf(state);
  const conversations = conversationsOf(openCount);
  const message = spokenUnless(isAutoplaying, conversations);
  const canReplay = isFinished && !isAutoplaying;

  function post() {
    const lineKey = state.openLine;
    act({ type: 'posted' });
    if (lineKey !== null) {
      schedule(() => act({ type: 'replied', lineKey }), REPLY_MS);
    }
  }

  function apply(lineKey: string) {
    act({ type: 'applying', lineKey });
    schedule(() => act({ type: 'applied', lineKey }), APPLY_MS);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full p-3 @3xl:p-8'
      >
        <div className='mx-auto flex max-w-3xl flex-col gap-4'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <BrandTile brand='github' size='lg' title='GitHub' />
            <div className='flex min-w-40 flex-1 flex-col leading-tight'>
              <h1 className='text-sm font-medium'>{PULL_REQUEST.title}</h1>
              <span className='text-muted-foreground text-xs'>
                {conversations}
              </span>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the review'
            />
          </header>

          <section
            aria-label={`Changes in ${PULL_REQUEST.file}`}
            className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
          >
            <div className='flex h-10 items-center gap-2 px-3'>
              <FileIcon className='text-muted-foreground size-4 shrink-0' />
              <span className='min-w-0 flex-1 truncate font-mono text-xs'>
                {PULL_REQUEST.file}
              </span>
              <span className='flex items-center gap-2 text-xs font-medium'>
                <MotionNumber
                  value={additions}
                  prefix='+'
                  className='text-success-foreground'
                />
                <MotionNumber
                  value={deletions}
                  prefix='-'
                  className='text-destructive-ink'
                />
              </span>
            </div>
            <ol className='pb-2'>
              {lines.map((line) => {
                const thread = state.threads.find(
                  (candidate) => candidate.lineKey === line.key
                );
                const isFieldOpen = state.openLine === line.key;
                const canComment = thread === undefined;
                return (
                  <li key={line.key}>
                    <DiffRow
                      line={line}
                      canComment={canComment}
                      isPlusPressed={pressed === `plus-${line.key}`}
                      onOpen={(lineKey) => act({ type: 'opened', lineKey })}
                    />
                    <AnimatePresence initial={false}>
                      {isFieldOpen && (
                        <motion.div
                          key='field'
                          className='overflow-hidden'
                          {...rowPresence}
                        >
                          <div className='p-2 @md:ps-9'>
                            <CommentField
                              draft={state.draft}
                              shouldFocus={!isAutoplaying}
                              isPostPressed={pressed === 'post'}
                              onChange={(text) => act({ type: 'typed', text })}
                              onPost={post}
                              onCancel={() => act({ type: 'closed' })}
                            />
                          </div>
                        </motion.div>
                      )}
                      {thread && (
                        <motion.div
                          key='thread'
                          className='overflow-hidden'
                          {...rowPresence}
                        >
                          <div className='p-2 @md:ps-9'>
                            <ReviewThread
                              thread={thread}
                              pressed={pressed}
                              onApply={apply}
                              onResolve={(lineKey) =>
                                act({ type: 'resolved', lineKey })
                              }
                              onToggleFold={(lineKey) =>
                                act({ type: 'folded', lineKey })
                              }
                            />
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </li>
                );
              })}
            </ol>
          </section>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { motion, useReducedMotion } from 'motion/react';

import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { ChevronDownIcon, CircleCheckIcon } from '@/registry/ndeko/lib/icons';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import {
  CODER,
  NOTE_REPLY,
  OLD_REPLY,
  OLD_THREAD_LINE,
  PULL_REQUEST,
  REVIEWER,
  SUGGESTION,
  SUGGESTION_REPLY,
  type LineKind,
} from './data';
import type { ApplyStatus, Thread } from './session';

const APPLY_LABELS: Record<MorphState, string> = {
  idle: 'Apply suggestion',
  busy: 'Applying',
  done: 'Applied',
};

const CHECK_PATH = 'M2.6 6.4 4.9 8.7 9.5 3.6';

const DRAW = { duration: 0.28, ease: EASE_OUT_STRONG, delay: 0.08 };

const SIGN: Record<LineKind, string> = { same: ' ', added: '+', removed: '-' };

const LINE_TINT: Record<LineKind, string> = {
  same: '',
  added: 'bg-success/10',
  removed: 'bg-destructive/10',
};

function strokeStartOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return { pathLength: 1 };
  }
  return { pathLength: 0 };
}

function DrawnCheck() {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className='chip-3d inline-flex size-[18px] items-center justify-center rounded-full [--chip:var(--success)]'>
      <svg aria-hidden='true' viewBox='0 0 12 12' className='size-3'>
        <motion.path
          d={CHECK_PATH}
          fill='none'
          stroke='currentColor'
          strokeWidth='1.9'
          strokeLinecap='round'
          strokeLinejoin='round'
          initial={strokeStartOf(shouldReduceMotion)}
          animate={{ pathLength: 1 }}
          transition={DRAW}
        />
      </svg>
    </span>
  );
}

function CoderTile() {
  const gemStyle = {
    '--gem': seriesColorOf(CODER.series),
  } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={gemStyle}
      className='gem-plate inline-flex size-6 shrink-0 items-center justify-center rounded-md text-[10px] font-semibold select-none'
    >
      {CODER.initial}
    </span>
  );
}

function TypingDots() {
  return (
    <span className='flex h-6 items-center gap-1' role='status'>
      <span className='sr-only'>Coder is writing a reply</span>
      <span className='bg-muted-foreground size-1.5 animate-pulse rounded-full' />
      <span className='bg-muted-foreground size-1.5 animate-pulse rounded-full [animation-delay:160ms]' />
      <span className='bg-muted-foreground size-1.5 animate-pulse rounded-full [animation-delay:320ms]' />
    </span>
  );
}

function morphStateOf(apply: ApplyStatus): MorphState {
  if (apply === 'busy') {
    return 'busy';
  }
  return 'idle';
}

function pressedSolidOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-primary/85';
  }
  return undefined;
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-foreground/[0.07]';
  }
  return undefined;
}

type SuggestionBlockProps = {
  apply: ApplyStatus;
  isPressed: boolean;
  onApply: () => void;
};

function SuggestionBlock({ apply, isPressed, onApply }: SuggestionBlockProps) {
  const isApplied = apply === 'done';

  return (
    <div className='bg-foreground/[0.04] flex flex-col gap-2 rounded-lg p-2'>
      <span className='text-muted-foreground px-1 text-xs'>
        Suggested change
      </span>
      <ol className='bg-card dark:bg-foreground/[0.04] overflow-hidden rounded-md py-1 font-mono text-xs leading-5'>
        {SUGGESTION.map((line) => (
          <li
            key={line.key}
            className={cn('flex gap-2 px-2', LINE_TINT[line.kind])}
          >
            <span
              aria-hidden='true'
              className='text-muted-foreground w-3 shrink-0 select-none'
            >
              {SIGN[line.kind]}
            </span>
            <code className='break-all whitespace-pre-wrap'>{line.text}</code>
          </li>
        ))}
      </ol>
      <div className='flex min-h-7 items-center px-1'>
        <Swap swapKey={String(isApplied)}>
          {!isApplied && (
            <MorphButton
              type='button'
              size='sm'
              state={morphStateOf(apply)}
              labels={APPLY_LABELS}
              onClick={onApply}
              className={pressedSolidOf(isPressed)}
            />
          )}
          {isApplied && (
            <span className='text-success-foreground flex items-center gap-1.5 text-xs font-medium'>
              <DrawnCheck />
              Applied in
              <code className='font-mono'>{PULL_REQUEST.commit}</code>
            </span>
          )}
        </Swap>
      </div>
    </div>
  );
}

function replyTextOf(thread: Thread) {
  if (thread.lineKey === OLD_THREAD_LINE) {
    return OLD_REPLY;
  }
  if (thread.reply === 'suggestion') {
    return SUGGESTION_REPLY;
  }
  return NOTE_REPLY;
}

function chevronOf(isFolded: boolean) {
  if (isFolded) {
    return 'rotate-0';
  }
  return 'rotate-180';
}

type ReviewThreadProps = {
  thread: Thread;
  pressed: string | null;
  onApply: (lineKey: string) => void;
  onResolve: (lineKey: string) => void;
  onToggleFold: (lineKey: string) => void;
};

export function ReviewThread({
  thread,
  pressed,
  onApply,
  onResolve,
  onToggleFold,
}: ReviewThreadProps) {
  const isTyping = thread.reply === 'typing';
  const hasSuggestion = thread.reply === 'suggestion';
  const isOpen = !thread.isFolded;

  return (
    <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] rounded-lg font-sans shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      {thread.isResolved && (
        <button
          type='button'
          aria-expanded={isOpen}
          onClick={() => onToggleFold(thread.lineKey)}
          className='hover:bg-foreground/[0.03] focus-visible:ring-ring/25 flex h-9 w-full cursor-pointer items-center gap-2 rounded-lg px-3 text-start text-xs outline-none focus-visible:ring-[3px]'
        >
          <CircleCheckIcon className='text-success-foreground size-4 shrink-0' />
          <span className='font-medium'>Resolved conversation</span>
          <span className='text-muted-foreground'>2 comments</span>
          <ChevronDownIcon
            className={cn(
              'text-muted-foreground ms-auto size-4 transition-transform duration-200 ease-(--ease-out-strong)',
              chevronOf(thread.isFolded)
            )}
          />
        </button>
      )}
      <Fold open={isOpen}>
        <div className='flex flex-col gap-3 p-3'>
          <div className='flex gap-2.5'>
            <Avatar className='size-6'>
              <AvatarImage src={REVIEWER.avatar} alt='' />
              <AvatarFallback className='text-[9px]'>
                {REVIEWER.initials}
              </AvatarFallback>
            </Avatar>
            <div className='flex min-w-0 flex-col'>
              <span className='text-xs leading-6 font-medium'>
                {REVIEWER.name}
              </span>
              <p className='text-[13px] leading-relaxed'>{thread.comment}</p>
            </div>
          </div>
          <div className='flex gap-2.5'>
            <CoderTile />
            <div className='flex min-w-0 flex-1 flex-col gap-2'>
              <span className='text-xs leading-6 font-medium'>
                {CODER.name}
              </span>
              {isTyping && <TypingDots />}
              {!isTyping && (
                <p className='text-[13px] leading-relaxed transition-opacity duration-300 starting:opacity-0'>
                  {replyTextOf(thread)}
                </p>
              )}
              {hasSuggestion && (
                <SuggestionBlock
                  apply={thread.apply}
                  isPressed={pressed === 'apply'}
                  onApply={() => onApply(thread.lineKey)}
                />
              )}
            </div>
          </div>
          {!thread.isResolved && (
            <div className='flex justify-end'>
              <Button
                type='button'
                variant='outline'
                size='sm'
                disabled={isTyping}
                onClick={() => onResolve(thread.lineKey)}
                className={pressedQuietOf(pressed === 'resolve')}
              >
                Resolve conversation
              </Button>
            </div>
          )}
        </div>
      </Fold>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  DEMO_COMMENT,
  OLD_COMMENT,
  OLD_THREAD_LINE,
  TARGET_LINE,
} from './data';

export type ReplyStatus = 'typing' | 'suggestion' | 'note';

export type ApplyStatus = 'idle' | 'busy' | 'done';

export type Thread = {
  lineKey: string;
  comment: string;
  reply: ReplyStatus;
  apply: ApplyStatus;
  isResolved: boolean;
  isFolded: boolean;
};

export type ReviewState = {
  /** The line whose comment field is open. */
  openLine: string | null;
  draft: string;
  threads: Thread[];
};

export type ReviewAction =
  | { type: 'opened'; lineKey: string }
  | { type: 'closed' }
  | { type: 'typed'; text: string }
  | { type: 'posted' }
  | { type: 'replied'; lineKey: string }
  | { type: 'applying'; lineKey: string }
  | { type: 'applied'; lineKey: string }
  | { type: 'resolved'; lineKey: string }
  | { type: 'folded'; lineKey: string };

type Step = SessionStep<ReviewState, ReviewAction>;

const OLD_THREAD: Thread = {
  lineKey: OLD_THREAD_LINE,
  comment: OLD_COMMENT,
  reply: 'note',
  apply: 'idle',
  isResolved: true,
  isFolded: true,
};

export const INITIAL: ReviewState = {
  openLine: null,
  draft: '',
  threads: [OLD_THREAD],
};

export function threadOf(state: ReviewState, lineKey: string) {
  return state.threads.find((thread) => thread.lineKey === lineKey);
}

export function hasGuardOf(state: ReviewState) {
  const target = threadOf(state, TARGET_LINE);
  return target?.apply === 'done';
}

function patched(
  state: ReviewState,
  lineKey: string,
  change: (thread: Thread) => Thread
): ReviewState {
  const threads = state.threads.map((thread) => {
    if (thread.lineKey === lineKey) {
      return change(thread);
    }
    return thread;
  });
  return { ...state, threads };
}

function commentOf(state: ReviewState) {
  const trimmed = state.draft.trim();
  if (trimmed === '') {
    return DEMO_COMMENT;
  }
  return trimmed;
}

function posted(state: ReviewState): ReviewState {
  const lineKey = state.openLine;
  if (lineKey === null) {
    return state;
  }
  const thread: Thread = {
    lineKey,
    comment: commentOf(state),
    reply: 'typing',
    apply: 'idle',
    isResolved: false,
    isFolded: false,
  };
  return {
    openLine: null,
    draft: '',
    threads: [...state.threads, thread],
  };
}

function replyFor(lineKey: string): ReplyStatus {
  if (lineKey === TARGET_LINE) {
    return 'suggestion';
  }
  return 'note';
}

function replied(thread: Thread): Thread {
  if (thread.reply !== 'typing') {
    return thread;
  }
  return { ...thread, reply: replyFor(thread.lineKey) };
}

function applying(thread: Thread): Thread {
  const canApply = thread.reply === 'suggestion' && thread.apply === 'idle';
  if (!canApply) {
    return thread;
  }
  return { ...thread, apply: 'busy' };
}

function applied(thread: Thread): Thread {
  if (thread.apply !== 'busy') {
    return thread;
  }
  return { ...thread, apply: 'done' };
}

function resolved(thread: Thread): Thread {
  if (thread.reply === 'typing') {
    return thread;
  }
  return { ...thread, isResolved: true, isFolded: true };
}

function folded(thread: Thread): Thread {
  return { ...thread, isFolded: !thread.isFolded };
}

function opened(state: ReviewState, lineKey: string): ReviewState {
  const hasThread = threadOf(state, lineKey) !== undefined;
  if (hasThread) {
    return state;
  }
  return { ...state, openLine: lineKey, draft: '' };
}

export function reducer(state: ReviewState, action: ReviewAction): ReviewState {
  switch (action.type) {
    case 'opened':
      return opened(state, action.lineKey);
    case 'closed':
      return { ...state, openLine: null, draft: '' };
    case 'typed':
      return { ...state, draft: action.text };
    case 'posted':
      return posted(state);
    case 'replied':
      return patched(state, action.lineKey, replied);
    case 'applying':
      return patched(state, action.lineKey, applying);
    case 'applied':
      return patched(state, action.lineKey, applied);
    case 'resolved':
      return patched(state, action.lineKey, resolved);
    case 'folded':
      return patched(state, action.lineKey, folded);
  }
}

const CHUNK = 2;

function delayOfChunk(index: number) {
  if (index === 0) {
    return 700;
  }
  return 60;
}

function typingSteps(): Step[] {
  const steps: Step[] = [];
  const last = DEMO_COMMENT.length + CHUNK;
  for (let end = CHUNK; end < last; end += CHUNK) {
    const text = DEMO_COMMENT.slice(0, end);
    const after = delayOfChunk(steps.length);
    steps.push({ after, by: 'demo', action: { type: 'typed', text } });
  }
  return steps;
}

function hasPosted(state: ReviewState) {
  return threadOf(state, TARGET_LINE) !== undefined;
}

function hasPressedApply(state: ReviewState) {
  const target = threadOf(state, TARGET_LINE);
  const apply = target?.apply ?? 'idle';
  return apply !== 'idle';
}

export const REPLY_MS = 1700;

export const APPLY_MS = 900;

/** A request that waits on a person is answered by the demonstration after this long. */
const DECIDE_AFTER_MS = 2500;

export const SCRIPT: Step[] = [
  {
    after: 1200,
    by: 'demo',
    press: `plus-${TARGET_LINE}`,
    action: { type: 'opened', lineKey: TARGET_LINE },
  },
  ...typingSteps(),
  {
    after: 500,
    by: 'person',
    press: 'post',
    action: { type: 'posted' },
    isAnswered: hasPosted,
  },
  { after: REPLY_MS, action: { type: 'replied', lineKey: TARGET_LINE } },
  {
    after: DECIDE_AFTER_MS,
    by: 'person',
    press: 'apply',
    action: { type: 'applying', lineKey: TARGET_LINE },
    isAnswered: hasPressedApply,
  },
  { after: APPLY_MS, action: { type: 'applied', lineKey: TARGET_LINE } },
  {
    after: 2200,
    by: 'demo',
    press: 'resolve',
    action: { type: 'resolved', lineKey: TARGET_LINE },
  },
];

function restingOf() {
  let state = INITIAL;
  for (const step of SCRIPT) {
    state = reducer(state, step.action);
  }
  const unfolded = reducer(state, { type: 'folded', lineKey: TARGET_LINE });
  return unfolded;
}

